import pytest

from numeric import integer_sqrt


def test_isqrt_negative_one():
    with pytest.raises(ValueError):
        integer_sqrt(-1)


def test_isqrt_negative_large():
    with pytest.raises(ValueError):
        integer_sqrt(-1000)


def test_isqrt_zero():
    assert integer_sqrt(0) == 0


def test_isqrt_one():
    assert integer_sqrt(1) == 1


def test_isqrt_two():
    assert integer_sqrt(2) == 1


def test_isqrt_three():
    assert integer_sqrt(3) == 1


def test_isqrt_four():
    assert integer_sqrt(4) == 2


def test_isqrt_fifteen():
    assert integer_sqrt(15) == 3


def test_isqrt_sixteen():
    assert integer_sqrt(16) == 4


def test_isqrt_hundred():
    assert integer_sqrt(100) == 10


def test_isqrt_hundred_one():
    assert integer_sqrt(101) == 10


def test_isqrt_one_hundred_nine_nine():
    assert integer_sqrt(1099) == 33


def test_isqrt_one_thousand():
    assert integer_sqrt(1000) == 31


def test_isqrt_large_perfect_square():
    # 46340^2 = 2147395600
    assert integer_sqrt(2147395600) == 46340


def test_isqrt_large_non_square():
    # 46340^2 = 2147395600, so 2147395601 should still have floor sqrt 46340
    assert integer_sqrt(2147395601) == 46340


def test_isqrt_just_below_next_square():
    # 46341^2 = 2147488281, so 2147488280 should have floor sqrt 46340
    assert integer_sqrt(2147488280) == 46340


def test_isqrt_at_next_square():
    # 46341^2 = 2147488281
    assert integer_sqrt(2147488281) == 46341

