import pytest

from containers import chunk


def test_chunk_empty_list():
    assert chunk([], 3) == []


def test_chunk_size_one():
    assert chunk([1, 2, 3], 1) == [[1], [2], [3]]


def test_chunk_size_larger_than_list():
    assert chunk([1, 2, 3], 10) == [[1, 2, 3]]


def test_chunk_single_element():
    assert chunk([42], 5) == [[42]]


def test_chunk_size_zero_raises():
    with pytest.raises(ValueError):
        chunk([1, 2, 3], 0)


def test_chunk_negative_size_raises():
    with pytest.raises(ValueError):
        chunk([1, 2, 3], -1)


def test_chunk_preserves_order():
    assert chunk([5, 3, 8, 1, 9, 2, 7], 3) == [[5, 3, 8], [1, 9, 2], [7]]


def test_chunk_with_strings():
    assert chunk(["a", "b", "c", "d"], 2) == [["a", "b"], ["c", "d"]]


def test_chunk_with_none_values():
    assert chunk([None, 1, None, 2], 2) == [[None, 1], [None, 2]]


def test_chunk_with_mixed_types():
    assert chunk([1, "a", 2, "b", 3], 2) == [[1, "a"], [2, "b"], [3]]

