import pytest

from containers import most_frequent


def test_raises_on_empty():
    with pytest.raises(ValueError):
        most_frequent([])


def test_single_item_returns_it():
    assert most_frequent([99]) == 99


def test_duplicate_majority():
    assert most_frequent(["cat", "dog", "cat", "cat", "dog"]) == "cat"


def test_tie_first_occurrence_wins():
    # 'b' appears at index 1, 'a' at index 0; both appear twice
    assert most_frequent(["a", "b", "a", "b"]) == "a"


def test_tie_later_first_occurrence():
    # 'z' first appears at index 0, 'm' at index 1; both appear 3 times
    assert most_frequent(["z", "m", "z", "m", "z", "m"]) == "z"


def test_unique_elements_returns_first():
    # All elements unique; each appears once; first occurrence wins
