import pytest
from parsers import parse_kv_pairs

def test_empty_text_returns_empty_dict():
    assert parse_kv_pairs("") == {}

def test_whitespace_only_returns_empty_dict():
    assert parse_kv_pairs("   \t\n  ") == {}

def test_single_pair_no_whitespace():
    assert parse_kv_pairs("a=1") == {"a": "1"}

def test_multiple_pairs_with_whitespace():
    assert parse_kv_pairs("  a = 1 , b = 2 , c = 3  ") == {"a": "1", "b": "2", "c": "3"}

def test_value_contains_equals_sign():
    # First '=' splits key and value; remaining '=' stays in value
    assert parse_kv_pairs("url=http://example.com?a=b") == {"url": "http://example.com?a=b"}

def test_entry_without_equals_raises_value_error():
    with pytest.raises(ValueError):
        parse_kv_pairs("a=1, bad, c=3")

def test_single_entry_without_equals_raises_value_error():
    with pytest.raises(ValueError):
        parse_kv_pairs("no_equals")

def test_empty_key_with_equals():
    # Key is empty string after strip
    assert parse_kv_pairs("=value") == {"": "value"}

def test_empty_value_with_equals():
    # Value is empty string after strip
    assert parse_kv_pairs("key=") == {"key": ""}

def test_whitespace_around_key_and_value_stripped():
    assert parse_kv_pairs("  key  =  value  ") == {"key": "value"}

